  requires (i >= 0)
  ensures (((i >= len(xs)) and (result == None)) or ((i < len(xs)) and (result == Some(xs[i]))))
  effects pure
  example (nth([5, 6, 7], 1) == Some(6))
  example (nth([5, 6, 7], 3) == None)
  example (nth([], 0) == None)
{
  match xs { [] => None [h, ..t] => if (i == 0) then Some(h) else nth(t, (i - 1)) }
}

