  ensures (len(result) == len(ys))
  ensures forall i in 0..len(ys): (result[i] == (ys[i] + k))
  effects pure
  example (add_each([1, 2], 10) == [11, 12])
  example (add_each([], 5) == [])
{
  match ys { [] => [] [y, ..r] => ([(y + k)] ++ add_each(r, k)) }
}

fn prefix_sums(xs: List[Int]) -> List[Int]
  requires (len(xs) >= 0)
  ensures (len(result) == len(xs))
  ensures forall i in 0..len(xs): (result[i] == sum(take(xs, (i + 1))))
  effects pure
  example (prefix_sums([1, 2, 3]) == [1, 3, 6])
  example (prefix_sums([]) == [])
  example (prefix_sums([5]) == [5])
{
  match xs { [] => [] [h, ..t] => ([h] ++ add_each(h, prefix_sums(t))) }
}

fn sum(xs: List[Int]) -> Int
  requires (len(xs) >= 0)
  ensures ((len(xs) == 0) or (result == (xs[0] + sum(drop(xs, 1)))))
  effects pure
  example (sum([]) == 0)
  example (sum([1, 2, 3]) == 6)
{
  match xs { [] => 0 [h, ..t] => (h + sum(t)) }
}

fn drop(xs: List[Int], k: Int) -> List[Int]
  requires ((k >= 0) and (k <= len(xs)))
  ensures (len(result) == (len(xs) - k))
  ensures forall i in 0..len(result): (result[i] == xs[(i + k)])
  effects pure
  example (drop([1, 2, 3], 1) == [2, 3])
  example (drop([1, 2, 3], 3) == [])
{
  if (k == 0) then xs else match xs { [] => [] [_, ..t] => drop(t, (k - 1)) }
}

fn take(xs: List[Int], n: Int) -> List[Int]
  requires ((n >= 0) and (n <= len(xs)))
  ensures (len(result) == n)
  ensures forall i in 0..n: (result[i] == xs[i])
  effects pure
  example (take([1, 2, 3], 2) == [1, 2])
  example (take([1, 2, 3], 0) == [])
{
  if (n == 0) then [] else match xs { [] => [] [h, ..t] => ([h] ++ take(t, (n - 1))) }
}

